PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  username TEXT,
  guild_id TEXT,
  coins INTEGER DEFAULT 0,
  total_distance_km REAL DEFAULT 0,
  total_trees_planted INTEGER DEFAULT 0,
  created_at INTEGER
, role TEXT DEFAULT 'user', player_id TEXT, nationality TEXT, bio TEXT, unlocked_badges TEXT, avatar TEXT, read_mails TEXT, muted_until INTEGER, banned_until INTEGER, showcased_badges TEXT, country TEXT, state TEXT, city TEXT, position TEXT, verified_email INTEGER DEFAULT 0);
CREATE TABLE activity_history (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  date TEXT NOT NULL,
  distance REAL NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE TABLE trees (
  id TEXT PRIMARY KEY,
  author_id TEXT NOT NULL,
  lng REAL NOT NULL,
  lat REAL NOT NULL,
  guild_id TEXT,
  planted_at INTEGER NOT NULL,
  FOREIGN KEY(author_id) REFERENCES users(id)
);
CREATE TABLE point_store (
  id TEXT PRIMARY KEY,
  merchant_id TEXT,
  category TEXT,
  name TEXT NOT NULL,
  desc TEXT,
  price INTEGER NOT NULL,
  stock INTEGER DEFAULT -1,
  icon TEXT
, status TEXT DEFAULT 'active', link TEXT);
CREATE TABLE signposts (
  id TEXT PRIMARY KEY,
  author_id TEXT NOT NULL,
  lng REAL NOT NULL,
  lat REAL NOT NULL,
  message TEXT,
  emoji TEXT,
  category TEXT,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL, likes INTEGER DEFAULT 0, liked_by TEXT DEFAULT "[]", images TEXT DEFAULT "[]",
  FOREIGN KEY(author_id) REFERENCES users(id)
);
CREATE TABLE mail (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  content TEXT NOT NULL,
  sender TEXT NOT NULL,
  recipient_type TEXT NOT NULL,
  recipient_id TEXT,
  expires_for_new_users INTEGER NOT NULL,
  created_at INTEGER NOT NULL
, recipient_name TEXT, action_type TEXT, action_data TEXT, sender_id TEXT);
CREATE TABLE merchants (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL,
  store_name TEXT NOT NULL,
  status TEXT NOT NULL,
  created_at INTEGER NOT NULL, menu_link TEXT, location TEXT,
  FOREIGN KEY(owner_id) REFERENCES users(id)
);
CREATE TABLE demo_requests (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  ip_address TEXT,
  status TEXT NOT NULL,
  requested_at INTEGER NOT NULL
);
CREATE TABLE store_categories (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL
);
CREATE TABLE purchases (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  merchant_id TEXT,
  item_id TEXT NOT NULL,
  item_name TEXT NOT NULL,
  price INTEGER NOT NULL,
  status TEXT DEFAULT 'active',
  purchased_at INTEGER NOT NULL,
  redeemed_at INTEGER, expires_at INTEGER,
  FOREIGN KEY(user_id) REFERENCES users(id),
  FOREIGN KEY(item_id) REFERENCES point_store(id)
);
CREATE TABLE applications (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL,
  type TEXT NOT NULL,
  details TEXT NOT NULL,
  status TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  FOREIGN KEY(owner_id) REFERENCES users(id)
);
CREATE TABLE global_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE guilds (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  members INTEGER DEFAULT 1,
  power INTEGER DEFAULT 0,
  avatar TEXT,
  banner TEXT,
  is_public INTEGER DEFAULT 1,
  created_at INTEGER
, icon TEXT DEFAULT '??', nationality TEXT DEFAULT 'Global', require_approval INTEGER DEFAULT 0, admin_id TEXT);
CREATE TABLE chat_messages (
  id TEXT PRIMARY KEY,
  guild_id TEXT NOT NULL,
  sender_id TEXT NOT NULL,
  sender_name TEXT NOT NULL,
  content TEXT NOT NULL,
  timestamp INTEGER NOT NULL
, is_edited INTEGER DEFAULT 0, attachment_key TEXT);
CREATE TABLE friends (
  user_id TEXT NOT NULL,
  friend_id TEXT NOT NULL,
  status TEXT DEFAULT 'pending', -- pending, accepted
  created_at INTEGER,
  PRIMARY KEY (user_id, friend_id)
);
CREATE TABLE user_read_mail (
  user_id TEXT NOT NULL,
  mail_id TEXT NOT NULL,
  read_at INTEGER,
  PRIMARY KEY (user_id, mail_id)
);
CREATE TABLE user_deleted_mail (
  user_id TEXT NOT NULL,
  mail_id TEXT NOT NULL,
  deleted_at INTEGER,
  PRIMARY KEY (user_id, mail_id)
);
CREATE TABLE user_chat_reads (user_id TEXT NOT NULL, guild_id TEXT NOT NULL, last_read_at INTEGER NOT NULL, PRIMARY KEY (user_id, guild_id));
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE infrastructure_reports (
  id                  TEXT PRIMARY KEY,
  author_id           TEXT NOT NULL,
  title               TEXT NOT NULL,
  description         TEXT,
  lng                 REAL NOT NULL,
  lat                 REAL NOT NULL,
  photos              TEXT,             
  status              TEXT NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'in-progress', 'resolved')),
  authority_response  TEXT,
  created_at          INTEGER NOT NULL, 
  updated_at          INTEGER NOT NULL, authority_id TEXT, deleted_at INTEGER, specific_location TEXT, resolved_at INTEGER, country TEXT, state TEXT, city TEXT, severity TEXT DEFAULT 'Minor', takedown_status TEXT, takedown_reason TEXT, 
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE RESTRICT
);
CREATE TABLE authority_tasks (
  id                  TEXT PRIMARY KEY,
  title               TEXT NOT NULL,
  description         TEXT,
  scheduled_at        INTEGER NOT NULL, 
  completed           INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
  created_by          TEXT NOT NULL,
  created_at          INTEGER NOT NULL, 
  updated_at          INTEGER NOT NULL, 
  deleted_at          INTEGER, importance TEXT DEFAULT 'Medium',          
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT
);
CREATE TABLE issue_messages (
  id          TEXT PRIMARY KEY,
  issue_id    TEXT NOT NULL,
  sender_id   TEXT NOT NULL,
  content     TEXT NOT NULL,
  created_at  INTEGER NOT NULL, image_url TEXT,
  FOREIGN KEY (issue_id) REFERENCES infrastructure_reports(id) ON DELETE CASCADE,
  FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE RESTRICT
);
CREATE TABLE authority_invitations (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  token_hash TEXT NOT NULL,
  expires_at INTEGER NOT NULL,
  used INTEGER DEFAULT 0 CHECK (used IN (0, 1)),
  created_at INTEGER NOT NULL,
  created_by TEXT NOT NULL, country TEXT, state TEXT, city TEXT,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT
);
CREATE TABLE report_activity (
  id TEXT PRIMARY KEY,
  report_id TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  actor_type TEXT NOT NULL,
  activity_type TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (report_id) REFERENCES infrastructure_reports(id) ON DELETE CASCADE
);
CREATE TABLE city_events (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  start_date INTEGER NOT NULL,
  end_date INTEGER NOT NULL,
  entry_fee INTEGER DEFAULT 0,
  promo_image TEXT,
  event_type TEXT NOT NULL,
  status TEXT DEFAULT 'active'
, early_end_reason TEXT);
CREATE TABLE city_event_badges (
  id TEXT PRIMARY KEY,
  event_id TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  icon_url TEXT NOT NULL,
  tier_level INTEGER NOT NULL,
  target_value INTEGER NOT NULL,
  FOREIGN KEY(event_id) REFERENCES city_events(id) ON DELETE CASCADE
);
CREATE TABLE city_event_participants (
  id TEXT PRIMARY KEY,
  event_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  joined_at INTEGER NOT NULL,
  starting_score INTEGER DEFAULT 0,
  badges_awarded TEXT DEFAULT '[]', frozen_score INTEGER,
  FOREIGN KEY(event_id) REFERENCES city_events(id) ON DELETE CASCADE,
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE city_event_submissions (
  id TEXT PRIMARY KEY,
  event_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  proof_url TEXT NOT NULL,
  description TEXT,
  status TEXT DEFAULT 'pending',
  created_at INTEGER NOT NULL,
  FOREIGN KEY(event_id) REFERENCES city_events(id) ON DELETE CASCADE,
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_users_username ON users(username);
CREATE UNIQUE INDEX idx_users_player_id ON users(player_id);
CREATE UNIQUE INDEX idx_guilds_name ON guilds(name);
CREATE INDEX idx_users_distance ON users(total_distance_km DESC);
CREATE INDEX idx_users_coins ON users(coins DESC);
CREATE INDEX idx_reports_status ON infrastructure_reports(status);
CREATE INDEX idx_reports_created_at ON infrastructure_reports(created_at);
CREATE INDEX idx_tasks_scheduled_at ON authority_tasks(scheduled_at);
CREATE INDEX idx_tasks_completed ON authority_tasks(completed);
CREATE INDEX idx_tasks_deleted_at ON authority_tasks(deleted_at);
CREATE INDEX idx_reports_lat_lng ON infrastructure_reports(lat, lng);
CREATE INDEX idx_reports_authority_id ON infrastructure_reports(authority_id);
CREATE INDEX idx_issue_messages_issue_id ON issue_messages(issue_id);
CREATE UNIQUE INDEX idx_authority_invitations_token ON authority_invitations(token_hash);
CREATE INDEX idx_authority_invitations_email ON authority_invitations(email);
CREATE INDEX idx_reports_jurisdiction ON infrastructure_reports(country, state, city);
CREATE INDEX idx_users_jurisdiction ON users(country, state, city);
CREATE INDEX idx_chat_messages_guild_timestamp ON chat_messages(guild_id, timestamp);
CREATE INDEX idx_issue_messages_created ON issue_messages(issue_id, created_at);
CREATE INDEX idx_report_activity_report_created ON report_activity(report_id, created_at);
